import { createSignal, createEffect } from 'solid-js';

// ❌ OLD: Reading 'logs()' inside the effect subscribes the effect to 'logs'.
// When 'setLogs' updates 'logs', the effect triggers itself in an infinite loop!
export default function TrackingLoop() {
  const [count, setCount] = createSignal(0);
  const [logs, setLogs] = createSignal([]);

  createEffect(() => {
    if (count() > 0) {
      // ❌ Reading logs() here creates a circular dependency:
      setLogs([...logs(), `Count is ${count()}`]);
    }
  });

  return <button onClick={() => setCount(c => c + 1)}>Increment</button>;
}

import { createSignal, createEffect, untrack } from 'solid-js';

// ✅ NEW: untrack() reads logs() without registering a subscription.
// The effect only re-runs when 'count()' changes.
export default function UntrackedEffect() {
  const [count, setCount] = createSignal(0);
  const [logs, setLogs] = createSignal([]);

  createEffect(() => {
    const currentCount = count(); // Tracked dependency
    if (currentCount > 0) {
      // ✅ untrack reads logs without subscribing:
      const currentLogs = untrack(logs);
      setLogs([...currentLogs, `Count is ${currentCount}`]);
    }
  });

  return <button onClick={() => setCount(c => c + 1)}>Increment</button>;
}
